DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.reservation_save(jsonb,uuid)'::regprocedure) INTO d; d:=replace(d,'BEGIN PERFORM pg_advisory_xact_lock(6281962);','BEGIN IF NOT staff THEN RAISE EXCEPTION ''Please call the centre to book a lane.''; END IF; PERFORM pg_advisory_xact_lock(6281962);'); d:=replace(d,$a$OR coalesce(p->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'$a$,$a$OR (coalesce(p->>'email','')<>'' AND coalesce(p->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')$a$); d:=replace(d,$a$trim(p->>'email')$a$,$a$trim(coalesce(p->>'email',''))$a$); EXECUTE d; END $$;
